<template>
  <section class="team-page page-section"><div class="container team-page__inner">
    <header class="team-head"><div><span>Доступы</span><h1 class="page-title">Команда и права</h1><p>Назначайте менеджеров из зарегистрированных пользователей. Удаление сотрудника заменено на отключение доступа — так история его действий и обработанных заказов не пропадает.</p></div><strong>{{ meta.total || users.length }} пользователей</strong></header>
    <div class="card team-toolbar"><label class="field"><span class="field__label">Найти по email</span><input v-model="search" class="field__input" placeholder="manager@example.ru"></label><label class="field"><span class="field__label">Месяц для расчёта KPI / зарплаты</span><input v-model="payrollMonth" class="field__input" type="month"></label><div class="team-toolbar__hint">Успешный заказ = статус «Завершён». Он засчитывается менеджеру, который был ответственным в момент завершения. Период считается по дате завершения заказа.</div></div>
    <div class="team-list">
      <article v-for="user in users" :key="user.id" class="card team-card" :class="{'is-disabled':!user.is_active}">
        <div class="team-card__identity"><div><strong>{{ user.email }}</strong><span>{{ roleLabel(user.role) }} · {{ user.email_verified_at?'email подтверждён':'email не подтверждён' }}</span></div><label class="team-active"><input v-model="user.is_active" type="checkbox"><span></span><b>{{ user.is_active?'Доступ включён':'Доступ отключён' }}</b></label></div>
        <div class="team-card__main">
          <label class="field"><span class="field__label">Роль</span><AppSelect v-model="user.role" :options="roleOptions" aria-label="Роль пользователя" /></label>
          <div v-if="user.role==='manager'" class="team-permissions"><strong>Разрешения менеджера</strong><label><input v-model="user.can_manage_orders" type="checkbox"> Заказы</label><label><input v-model="user.can_manage_catalog" type="checkbox"> Товары и категории</label><label><input v-model="user.can_manage_discounts" type="checkbox"> Скидки</label><label><input v-model="user.can_manage_campaigns" type="checkbox"> Рассылки</label></div>
          <div v-if="user.role==='manager'" class="team-stats"><div><span>Успешных за {{ payrollMonthLabel }}</span><strong>{{ user.success_orders_period }}</strong></div><div><span>Успешных всего</span><strong>{{ user.success_orders_all }}</strong></div><div><span>Сейчас в работе</span><strong>{{ user.active_orders }}</strong></div></div>
        </div>
        <div class="team-card__foot"><small v-if="user.id===auth.user?.id">Это ваш аккаунт. Последнего активного администратора система не даст отключить или понизить.</small><span v-else></span><button class="btn btn--primary team-card__save" :class="{'is-loading':savingVisible===user.id}" :disabled="saving===user.id" :aria-busy="saving===user.id" @click="save(user)"><span>Сохранить права</span></button></div>
      </article>
    </div>
    <p v-if="!users.length" class="card team-empty">Пользователи не найдены.</p>
  </div></section>
</template>
<script setup>
import AppSelect from '~/components/ui/AppSelect.vue'
definePageMeta({layout:'admin',middleware:'admin'})
import {useAuthStore} from '~/stores/auth';import {useNotificationsStore} from '~/stores/notifications';import {createApiUrl} from '~/utils/api'
const auth=useAuthStore(),notifications=useNotificationsStore(),users=ref([]),meta=reactive({total:0}),search=ref(''),saving=ref(null),savingVisible=ref(null)
const roleOptions=[{value:'user',label:'Покупатель'},{value:'manager',label:'Менеджер'},{value:'admin',label:'Администратор'}]
const now=new Date();const payrollMonth=ref(`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`)
const payrollRange=computed(()=>{const [y,m]=payrollMonth.value.split('-').map(Number);if(!y||!m)return{};return{stats_from:new Date(y,m-1,1).toISOString(),stats_to:new Date(y,m,1).toISOString()}})
const payrollMonthLabel=computed(()=>{const [y,m]=payrollMonth.value.split('-').map(Number);return y&&m?new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(y,m-1,1)): 'период'})
const load=async()=>{const r=await auth.authFetch(createApiUrl('/staff/admin/users'),{query:{search:search.value,limit:100,...payrollRange.value}});users.value=r.items;Object.assign(meta,r.meta||{})}
let timer;let savingFeedbackTimer;let savingShownAt=0
watch([search,payrollMonth],()=>{clearTimeout(timer);timer=setTimeout(load,300)})
onBeforeUnmount(()=>{clearTimeout(timer);clearTimeout(savingFeedbackTimer)})
onMounted(async()=>{if(!auth.is_initialized)await auth.initAuth();await load()})
const beginSavingFeedback=id=>{saving.value=id;savingVisible.value=null;clearTimeout(savingFeedbackTimer);savingFeedbackTimer=setTimeout(()=>{if(saving.value===id){savingShownAt=Date.now();savingVisible.value=id}},180)}
const endSavingFeedback=async id=>{clearTimeout(savingFeedbackTimer);if(savingVisible.value===id){const remaining=Math.max(0,260-(Date.now()-savingShownAt));if(remaining)await new Promise(resolve=>setTimeout(resolve,remaining))}if(saving.value===id)saving.value=null;if(savingVisible.value===id)savingVisible.value=null}
const save=async user=>{if(saving.value!==null)return;beginSavingFeedback(user.id);try{const payload={role:user.role,is_active:user.is_active,can_manage_orders:user.role==='manager'&&user.can_manage_orders,can_manage_catalog:user.role==='manager'&&user.can_manage_catalog,can_manage_discounts:user.role==='manager'&&user.can_manage_discounts,can_manage_campaigns:user.role==='manager'&&user.can_manage_campaigns};await auth.authFetch(createApiUrl(`/staff/admin/users/${user.id}`),{method:'PATCH',body:payload});notifications.success('Права сотрудника сохранены');await load()}catch(e){notifications.error(e?.data?.message||e?.response?._data?.message||'Не удалось сохранить права')}finally{await endSavingFeedback(user.id)}}
const roleLabel=r=>r==='admin'?'Администратор':r==='manager'?'Менеджер':'Покупатель'
</script>
<style scoped lang="scss">
