:repeat(2,minmax(0,1fr));gap:9px;padding:12px;border-radius:13px;background:#faf6ef}.team-permissions strong{grid-column:1/-1;color:#5c4c3c;font-size:11px}.team-permissions label{display:flex;align-items:center;gap:7px;color:#6f6357;font-size:12px}.team-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.team-stats div{display:grid;gap:3px;padding:11px;border:1px solid rgba(111,82,48,.08);border-radius:12px;background:#fff}.team-stats span{color:#8b8074;font-size:10px}.team-stats strong{color:#382a1c;font-size:20px}.team-card__foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:14px}.team-card__foot small{max-width:650px;color:#918477}.team-card__foot .btn{min-height:40px}.team-card__save{width:174px;white-space:nowrap}.team-card__save:disabled{opacity:1;cursor:wait}.team-card__save.is-loading span{opacity:.9}.team-empty{padding:30px;text-align:center}@media(max-width:900px){.team-card__main{grid-template-columns:1fr}.team-toolbar{grid-template-columns:1fr}.team-stats{max-width:520px}}@media(max-width:600px){.team-head,.team-card__identity,.team-card__foot{align-items:stretch;flex-direction:column}.team-active{white-space:normal}.team-permissions,.team-stats{grid-template-columns:1fr}.team-card__foot .btn{width:100%}}
</style>
